SRC = open(ROOT + "/sources/paper.tex").read()


def ev(q):
    return {"source": "paper", "quote": q}


def mot(text, source, quote=None):
    d = {"text": text, "source": source}
    d["quote"] = ev(quote) if quote else None
    return d


def B(symbol, name, meaning, relation="direct"):
    return {"symbol": symbol, "name": name, "meaning": meaning, "relation": relation}


def infer(id, claim, quote, from_=(), deferred=False, salient=None, page=None):
    d = {"id": id, "intention": "infer", "claim": claim, "quote": ev(quote), "from": list(from_)}
    if deferred:
        d["deferred"] = True
    if salient:
        d["salient"] = salient
    if page:
        d["page"] = page
    return d


def show(id, claim, method, motivation, children, page=None, from_=(), salient=None, adds=()):
    d = {"id": id, "intention": "show", "claim": claim, "method": method,
         "motivation": motivation, "children": children, "from": list(from_)}
    if page:
        d["page"] = page
    if salient:
        d["salient"] = salient
    if adds:
        d["adds"] = list(adds)
    return d


